declare(strict_types=1);if(getenv('RUN_PLATFORM02_MARIADB_TESTS')!=='1'){echo "TenantSchemaInspectorMariaDb SKIPPED\n";exit;}require __DIR__.'/../vendor/autoload.php';use MiniErp\Platform\{TenantSchemaComparator,TenantSchemaInspector};$c=require __DIR__.'/../config.php';$d=$c['db'];$pdo=new PDO(sprintf('mysql:host=%s;port=%s;charset=utf8mb4',$d['host'],$d['port']),$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db='mini_erp_tenant_999997';try{$pdo->exec("CREATE DATABASE `{$db}` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$pdo->exec("CREATE TABLE `{$db}`.sample(id BIGINT PRIMARY KEY,other VARCHAR(10),UNIQUE KEY uq_other(other)) ENGINE=InnoDB");$i=new TenantSchemaInspector($pdo);$actual=$i->inspect($db);$expected=['tables'=>['sample'=>['engine'=>'InnoDB','collation'=>'utf8mb4_unicode_ci','columns'=>['id'=>['COLUMN_TYPE'=>'int','IS_NULLABLE'=>'NO','COLUMN_DEFAULT'=>null,'COLUMN_KEY'=>'PRI','EXTRA'=>''],'missing'=>['COLUMN_TYPE'=>'varchar(5)','IS_NULLABLE'=>'YES','COLUMN_DEFAULT'=>null,'COLUMN_KEY'=>'','EXTRA'=>'']],'indexes'=>['PRIMARY'=>[],'missing_index'=>[]],'foreign_keys'=>['missing_fk'=>[]]]]];$r=(new TenantSchemaComparator)->compare($expected,$actual);$k=array_column($r['differences'],'kind');foreach(['MISSING_COLUMN','COLUMN_PROPERTY','MISSING_INDEX','MISSING_FK','EXTRA_COLUMN','EXTRA_INDEX'] as $kind)if(!in_array($kind,$k,true))throw new RuntimeException($kind);try{$i->tableRows($db,'not_allowed');throw new RuntimeException('whitelist');}catch(RuntimeException $e){if($e->getMessage()==='whitelist')throw $e;}echo "TenantSchemaInspectorMariaDb OK\n";}finally{$pdo->exec("DROP DATABASE IF EXISTS `{$db}`");}
